const SYSTEM_PROMPT = `Du strukturierst deutschsprachige physiotherapeutische Sitzungsdiktate.

Gegeben ist ein frei gesprochenes Diktat nach einer Behandlung, ohne Labels oder feste Reihenfolge. Extrahiere ausschliesslich Information, die explizit im Diktat genannt wird, in vier Kategorien:

- befund: Beschwerde, Befund oder Beobachtung, die explizit genannt wird (z. B. Schmerzlokalisation, Ausloeser, Vorgeschichte)
- therapie: durchgefuehrte Behandlung(en)/Intervention(en), die explizit genannt werden -- jede einzelne Massnahme als eigener Listeneintrag
- verlauf: Veraenderung, Reaktion oder Entwicklung seit der letzten Sitzung, die explizit genannt wird
- fokus: Plan oder Schwerpunkt fuer die naechste Sitzung, NUR wenn explizit genannt

Regeln:
1. Nur Information verwenden, die explizit im Diktat steht. Nichts hinzufuegen, nichts erfinden.
2. Keine Diagnosen stellen, keine medizinischen Schlussfolgerungen ziehen, die nicht genannt wurden.
3. Ursache, Dauer, Verbesserung, naechste Schritte NICHT ergaenzen, wenn nicht genannt.
4. Wenn eine Kategorie nicht vorkommt: leeres Array zurueckgeben.
5. Bei materieller Unklarheit: die Unsicherheit beibehalten statt zu raten -- Originalformulierung uebernehmen statt zu interpretieren.
6. Originalformulierung so weit wie moeglich beibehalten -- nur zuordnen und strukturieren, nicht umformulieren oder ausschmuecken.
7. Standard-Fachkuerzel (HWS, BWS, LWS) duerfen im Originaltext erhalten bleiben, wenn Gerrit sie so sagt.
8. Gerrit muss KEINE Labels wie 'Befund:' oder 'Therapie:' sagen -- die Zuordnung erfolgt ausschliesslich anhand der inhaltlichen Bedeutung.

Antworte ausschliesslich mit einem JSON-Objekt, exakt im vorgegebenen Schema.`;

const SCHEMA = {
  type: "object",
  properties: {
    befund: { type: "array", items: { type: "string" } },
    therapie: { type: "array", items: { type: "string" } },
    verlauf: { type: "array", items: { type: "string" } },
    fokus: { type: "array", items: { type: "string" } }
  },
  required: ["befund", "therapie", "verlauf", "fokus"],
  additionalProperties: false
};

const body = $input.first().json.body || {};
const transcript = typeof body.transcript === "string" ? body.transcript.trim() : "";

if (!transcript) {
  return [{ json: { ok: false, error: "transcript required", statusCode: 400 } }];
}
if (transcript.length > 10000) {
  return [{ json: { ok: false, error: "transcript too long", statusCode: 400 } }];
}

// PILOT: smallest-effort correct default -- reuses the exact model+endpoint
// already proven live for this OpenAI credential (HI product), so the FIRST
// natural-dictation proof is not also a model-compatibility gamble. This is a
// single field: swap to a cheaper sibling once correctness is proven and cost
// data (see usage logging downstream) shows it is worth optimizing.
const MODEL = "gpt-5.5-2026-04-23";

const openai_request_body = {
  model: MODEL,
  input: [
    { role: "system", content: [{ type: "input_text", text: SYSTEM_PROMPT }] },
    { role: "user", content: [{ type: "input_text", text: transcript }] }
  ],
  text: { format: { type: "json_schema", name: "session_note", strict: true, schema: SCHEMA } }
};

return [{ json: { ok: true, openai_request_body } }];

const json = $input.first().json;

if (json.error) {
  return [{ json: { ok: false, error: "Upstream OpenAI request failed", statusCode: 502 } }];
}

try {
  const messageItem = Array.isArray(json.output) ? json.output.find((o) => o.type === "message") : null;
  const textContent = messageItem && messageItem.content && messageItem.content.find((c) => c.text !== undefined);
  if (!textContent) {
    return [{ json: { ok: false, error: "No structured output in OpenAI response", statusCode: 502 } }];
  }
  const parsed = typeof textContent.text === "object" ? textContent.text : JSON.parse(textContent.text);

  const toArray = (v) => Array.isArray(v) ? v.filter((s) => typeof s === "string" && s.trim()).map((s) => s.trim()) : [];

  const result = {
    befund: toArray(parsed.befund),
    therapie: toArray(parsed.therapie),
    verlauf: toArray(parsed.verlauf),
    fokus: toArray(parsed.fokus)
  };

  // Minimal cost observability (execution-log only, no dashboard/db):
  const usage = json.usage || {};
  console.log(`[frame-gerrit usage] model=${json.model || "unknown"} input_tokens=${usage.input_tokens ?? "?"} output_tokens=${usage.output_tokens ?? "?"} total_tokens=${usage.total_tokens ?? "?"}`);

  return [{ json: { ok: true, statusCode: 200, ...result } }];
} catch (e) {
  return [{ json: { ok: false, error: "Could not parse structured response", statusCode: 502 } }];
}
